import { useEffect, useState } from 'react';

export function useScript(src: string) {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let script = document.querySelector(`script[src="${src}"]`);
    if (src.indexOf('https://oapi.map.naver.com/openapi/v3/') > -1) {
      script = document.querySelector(`[src="https://oapi.map.naver.com/openapi/v3/maps-geocoder.js"]`);
    }
    const handleLoad = (load: any) => {
      setLoading(false);
    };
    const handleError = (err: any) => {
      setError(err);
      setLoading(false);
    };
    if (!script) {
      script = document.createElement('script');
      (script as any).src = src;
      (script as any).type = 'text/javascript';
      (script as any).charset = 'utf-8';

      script.addEventListener('load', handleLoad);
      script.addEventListener('error', handleError);
      document.getElementsByTagName('head')[0].appendChild(script);
    } else {
      setLoading(false);
    }

    return () => {
      script.removeEventListener('load', handleLoad);
      script.removeEventListener('error', handleError);
      script.remove();
    };
  }, [src]);

  return [loading, error];
}
